; UART transmitter, 8N1, 115200 baud; one byte per host mailbox word
; Generated by escgen from protocols/uart_tx_gen.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: TIA-232-F character format: start bit, 8 data bits LSB first, stop bit
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ BIT, (CLK_KHZ * 1000 + 57600) // 115200
.default PIN_TX, 0
.equ P_TX, 1 << PIN_TX

.own  PIN_TX, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_TX, P_TX, P_TX            ; idle levels
    ADDT  1
packet:
    POP   r0                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    EMIT  P_TX, 0, P_TX               ; start
    ADDT  BIT
    LDSH  r0                          ; 8 bits, LSB first
    LDLC  8
bit1:
    EMITX P_TX, LSB, P_TX             ; data bit
    ADDT  BIT
    DJNZ  bit1
    EMIT  P_TX, P_TX, P_TX            ; stop
    ADDT  BIT
    JMP   packet
